using Microsoft.AspNetCore.Mvc;
using Sigov.Api.Middlewares;
using Sigov.Application.Common;
using Sigov.Application.Saneamento;
using Sigov.Domain.Common;

namespace Sigov.Api.Controllers;

[ApiController]
[RequireModule("saneamento")]
public abstract class SaneamentoApiControllerBase : ControllerBase
{
    protected ActionResult<ApiResponse<T>> FromResult<T>(Result<T> result)
    {
        if (result.IsSuccess) return Ok(ApiResponse<T>.Ok(result.Value!));
        var error = result.Error ?? "Falha na operação.";
        return error.Contains("permiss", StringComparison.OrdinalIgnoreCase) || error.Contains("módulo", StringComparison.OrdinalIgnoreCase) ? StatusCode(StatusCodes.Status403Forbidden, ApiResponse<T>.Fail(error)) : BadRequest(ApiResponse<T>.Fail(error));
    }
    protected ActionResult<ApiResponse<object>> FromResult(Result result)
    {
        if (result.IsSuccess) return Ok(ApiResponse<object>.Ok(new { }));
        var error = result.Error ?? "Falha na operação.";
        return error.Contains("permiss", StringComparison.OrdinalIgnoreCase) || error.Contains("módulo", StringComparison.OrdinalIgnoreCase) ? StatusCode(StatusCodes.Status403Forbidden, ApiResponse<object>.Fail(error)) : BadRequest(ApiResponse<object>.Fail(error));
    }
}

